<script lang="ts">import {model,setPreference,demo,replayEntrance,openIntegration} from '../model';import {isNative} from '../bridge';import {INTEGRATIONS} from '../integrations';import Icon from './Icon.svelte';import IntegrationDetail from './integrations/IntegrationDetail.svelte';export let integrations=false;</script>
<div class="settings">{#if integrations}{#if $model.integration}<IntegrationDetail id={$model.integration}/>{:else}<h2>Intégrations</h2>{#each INTEGRATIONS as p}<button class="row link" style={`--pill:${p.color}`} onclick={()=>openIntegration(p.id)}><span class="label"><span class="mark"><Icon name={p.icon}/></span>{p.name}</span><span class="trail"><Icon name="chevron"/></span></button>{/each}{/if}{:else}<h2>Réglages</h2><label class="row"><span>Animations</span><input type="checkbox" checked={$model.motion} onchange={e=>setPreference('motion',e.currentTarget.checked)}/></label><label class="row"><span>Son pour les demandes</span><input type="checkbox" checked={$model.sound} onchange={e=>setPreference('sound',e.currentTarget.checked)}/></label><div class="row"><span>Axon</span><small class:online={$model.connected}>{$model.demo?'démonstration':$model.connected?'connecté':'hors ligne'}</small></div>{#if !isNative()&&!$model.connected}<button class="preview" onclick={demo}>Essayer la démo</button>{/if}<button class="preview" disabled={!$model.motion||$model.requests.length>0} onclick={replayEntrance}>Rejouer l’arrivée d’Axon</button>{/if}</div>
<style>.settings{height:100%;overflow:auto;padding:2px 6px}h2{font-size:16px;font-weight:500;letter-spacing:-.3px;margin-bottom:8px}.row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:15px 0;border-bottom:1px solid #ffffff06;font-size:12px}.row small{color:var(--faint);font:9px var(--mono)}small.online{color:#83b8a0}input{accent-color:var(--accent);width:15px;height:15px}.preview{border:1px solid #ffaf0028;border-radius:18px;color:#dfb86e;font-size:11px;padding:8px 12px;margin-top:15px}.row.link{width:100%;text-align:left;transition:transform 160ms var(--spring),border-color 150ms;border-radius:10px;padding:10px 8px;border-bottom:1px solid #ffffff06}.row.link:hover{transform:translateX(2px);border-color:color-mix(in srgb,var(--pill) 40%,#ffffff06)}.label{display:flex;align-items:center;gap:10px;font-size:12px}.mark{width:26px;height:26px;border-radius:9px;display:grid;place-items:center;color:var(--pill);background:color-mix(in srgb,var(--pill) 16%,#ffffff08);border:1px solid color-mix(in srgb,var(--pill) 30%,transparent);flex:none}.trail{display:flex;align-items:center;gap:6px;color:var(--faint)}.trail :global(svg){width:13px;height:13px;opacity:.7}</style>
